{
  "cvars": {
    "ivs": [
      {
        "description": "Name femininity rating (continuous) — higher values = more feminine name",
        "columns": [
          "masfem_c"
        ]
      }
    ],
    "dv": {
      "description": "Proxy for precautionary behavior outcome: log-transformed total deaths caused by the hurricane (assumes fewer precautions -> more deaths)",
      "columns": [
        "log_alldeaths"
      ]
    },
    "controls": [
      {
        "description": "Maximum sustained wind speed at landfall (control for storm intensity)",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "wind"
        ]
      },
      {
        "description": "Minimum pressure at landfall (control for storm intensity; lower = stronger)",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "min"
        ]
      },
      {
        "description": "Saffir\u2013Simpson category (ordinal control for storm intensity)",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "category"
        ]
      },
      {
        "description": "Years elapsed since the storm (controls for historical reporting / changes over time)",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "elapsedyrs"
        ]
      },
      {
        "description": "Binary gender label of name (0=male, 1=female) included as robustness control",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "gender_mf"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Make a copy to avoid modifying caller's dataframe\n    df = df.copy()\n\n    # Ensure numeric columns are numeric\n    numeric_cols = ['masfem', 'masfem_mturk', 'min', 'category', 'alldeaths', 'ndam15', 'wind', 'elapsedyrs', 'gender_mf']\n    for col in numeric_cols:\n        if col in df.columns:\n            df[col] = pd.to_numeric(df[col], errors='coerce')\n\n    # Drop rows missing key variables needed for the main model\n    required = ['masfem', 'alldeaths', 'wind', 'min', 'category', 'elapsedyrs']\n    df = df.dropna(subset=[c for c in required if c in df.columns])\n\n    # Dependent variable: log(1 + total deaths) to reduce skew and handle zeros\n    df['log_alldeaths'] = np.log1p(df['alldeaths'].astype(float))\n\n    # Independent variable: center masfem for interpretability\n    df['masfem_c'] = df['masfem'].astype(float) - df['masfem'].astype(float).mean()\n\n    # Include alternative IV (binary name-gender) kept as-is for robustness checks\n    if 'gender_mf' in df.columns:\n        df['gender_mf'] = df['gender_mf'].astype(int)\n\n    # Ensure categorical/ordinal variable 'category' is numeric (already numeric in schema)\n    df['category'] = pd.to_numeric(df['category'], errors='coerce')\n\n    # Optionally create a simple severity index (z-scored) combining wind and inverse pressure\n    df['wind_z'] = (df['wind'] - df['wind'].mean()) / (df['wind'].std(ddof=0) if df['wind'].std(ddof=0) != 0 else 1)\n    df['min_inv_z'] = ((-df['min']) - (-df['min']).mean()) / ((-df['min']).std(ddof=0) if (-df['min']).std(ddof=0) != 0 else 1)\n    df['severity_z'] = df[['wind_z', 'min_inv_z', 'category']].apply(lambda row: np.nanmean([row['wind_z'], row['min_inv_z'], (row['category'] - df['category'].mean()) / (df['category'].std(ddof=0) if df['category'].std(ddof=0) != 0 else 1)]), axis=1)\n\n    # Final column list used in the model (kept in the dataframe)\n    # ['log_alldeaths', 'masfem_c', 'wind', 'min', 'category', 'elapsedyrs', 'gender_mf', 'severity_z']\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> float:\n    # Model: OLS predicting log deaths from centered name femininity controlling for storm intensity and time\n    # Require that transform(df) has been run so masfem_c and log_alldeaths exist\n    import statsmodels.api as sm\n\n    df_model = df.dropna(subset=['log_alldeaths', 'masfem_c', 'wind', 'min', 'category', 'elapsedyrs'])\n\n    # Predictors: masfem_c (IV) + severity controls. Use severity components as separate controls for transparency.\n    X = df_model[['masfem_c', 'wind', 'min', 'category', 'elapsedyrs']].astype(float)\n    X = sm.add_constant(X)\n    y = df_model['log_alldeaths'].astype(float)\n\n    ols_res = sm.OLS(y, X).fit()\n\n    # Key summary metric: estimated coefficient on masfem_c (effect of a one-unit increase in name femininity on log deaths)\n    coef_masfem = float(ols_res.params.get('masfem_c', np.nan))\n\n    # Optionally, one might return p-value or standardized effect. Here we return the raw coefficient as the primary summary.\n    return coef_masfem\n"
}

{
  "cvars": {
    "ivs": [
      {
        "description": "Feminine quality of the hurricane name (continuous). Higher values mean the name was rated as more feminine by independent coders.",
        "columns": [
          "masfem",
          "masfem_c"
        ]
      },
      {
        "description": "Binary indicator for female name (alternative operationalization: 1 = female name, 0 = male name).",
        "columns": [
          "gender_mf"
        ]
      }
    ],
    "dv": {
      "description": "Log-transformed hurricane fatalities: log(alldeaths + 1). This is used as a proxy for how effective public precautionary responses were (higher fatalities consistent with fewer/less effective precautions after accounting for storm strength).",
      "columns": [
        "alldeaths",
        "LogDeaths"
      ]
    },
    "controls": [
      {
        "description": "Maximum sustained wind speed at landfall (controls for storm intensity).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "wind"
        ]
      },
      {
        "description": "Saffir\u2013Simpson category at landfall (controls for storm intensity).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "category"
        ]
      },
      {
        "description": "Minimum pressure at landfall (controls for storm intensity; lower pressure = stronger storm).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "min"
        ]
      },
      {
        "description": "Year of the storm (controls for improvements in forecasting, infrastructure and reporting over time).",
        "is_moderator": false,
        "moderator_on": null,
        "columns": [
          "year"
        ]
      }
    ]
  },
  "transform_code": "def transform(df: pd.DataFrame) -> pd.DataFrame:\n    # Work on a copy\n    df = df.copy()\n\n    # Ensure numeric columns are numeric, coerce errors to NaN\n    numeric_cols = ['alldeaths', 'masfem', 'gender_mf', 'wind', 'category', 'min', 'year', 'ndam15']\n    for c in numeric_cols:\n        if c in df.columns:\n            df[c] = pd.to_numeric(df[c], errors='coerce')\n\n    # Drop rows missing the key variables needed for the primary analysis\n    required = [c for c in ['alldeaths', 'masfem', 'wind', 'category', 'min', 'year'] if c in df.columns]\n    df = df.dropna(subset=required)\n\n    # Create the dependent variable: log deaths as proxy for precautionary failure\n    df['LogDeaths'] = np.log(df['alldeaths'] + 1)\n\n    # Center the masfem variable for clearer interpretation of the intercept\n    df['masfem_c'] = df['masfem'] - df['masfem'].mean()\n\n    # Optionally keep the binary gender indicator (alternative IV)\n    if 'gender_mf' in df.columns:\n        df['gender_mf'] = df['gender_mf'].astype(float)\n\n    # Keep only columns needed for modeling and interpretation\n    keep = ['LogDeaths', 'alldeaths', 'masfem', 'masfem_c', 'gender_mf', 'wind', 'category', 'min', 'year', 'ndam15', 'name']\n    keep = [c for c in keep if c in df.columns]\n    df = df[keep]\n\n    return df\n",
  "m_code": "def model(df: pd.DataFrame) -> float:\n    # Make a local copy\n    df = df.copy()\n\n    # Build design matrix for OLS on log(deaths)\n    # Primary model: LogDeaths ~ masfem_c + wind + category + min + year\n    X_cols = [c for c in ['masfem_c', 'wind', 'category', 'min', 'year'] if c in df.columns]\n    X = df[X_cols]\n    X = sm.add_constant(X)\n    y = df['LogDeaths']\n\n    # Fit OLS (robust standard errors could be added; primary quantity returned is the masfem coefficient)\n    model = sm.OLS(y, X, missing='drop').fit()\n\n    # Return the estimated coefficient on the centered masfem variable (effect of a one-unit increase in femininity\n    # on log fatalities, controlling for storm strength and year). If masfem_c not in model, return NaN.\n    if 'masfem_c' in model.params.index:\n        coef = float(model.params['masfem_c'])\n    else:\n        coef = float('nan')\n\n    return coef\n"
}
